local_load_timeinterval <- function() {
  if (exists("timeinterval", mode = "function")) return(invisible(TRUE))
  if ("ClinicoPath" %in% loadedNamespaces() &&
      exists("timeinterval", where = asNamespace("ClinicoPath"), mode = "function")) {
    assign("timeinterval", get("timeinterval", envir = asNamespace("ClinicoPath")), envir = .GlobalEnv)
    assign("timeintervalClass", get("timeintervalClass", envir = asNamespace("ClinicoPath")), envir = .GlobalEnv)
    assign("timeintervalOptions", get("timeintervalOptions", envir = asNamespace("ClinicoPath")), envir = .GlobalEnv)
    return(invisible(TRUE))
  }
  suppressPackageStartupMessages({
    library(jmvcore)
    library(R6)
  })
  root <- testthat::test_path("../..")
  source(file.path(root, "R/utils.R"), local = .GlobalEnv)
  source(file.path(root, "R/timeinterval.h.R"), local = .GlobalEnv)
  source(file.path(root, "R/timeinterval.b.R"), local = .GlobalEnv)
  invisible(TRUE)
}

ti_vals <- function(res) {
  v <- res$calculated_time$.__enclos_env__$private$.values
  if (is.null(v)) return(NULL)
  unlist(v, use.names = FALSE)
}

ti_rownums <- function(res) {
  res$calculated_time$.__enclos_env__$private$.rowNums
}

ti_stat <- function(html_txt, label) {
  m <- regexec(paste0(label, ": ([0-9.eE+\\-]+)"), html_txt)
  z <- regmatches(html_txt, m)[[1]]
  if (length(z) != 2L) return(NA_real_)
  as.numeric(z[2L])
}

ti_ci <- function(html_txt, conf_level = 95) {
  pat <- paste0("\\(", conf_level, "% CI: ([0-9.eE+\\-]+) to ([0-9.eE+\\-]+)")
  m <- regexec(pat, html_txt)
  z <- regmatches(html_txt, m)[[1]]
  if (length(z) != 3L) return(c(NA_real_, NA_real_))
  as.numeric(z[2:3])
}

test_that("timeinterval matches hand-calculated standardized intervals across all 4 units and 8 formats", {
  local_load_timeinterval()
  df <- data.frame(
    s = c("2020-01-01", "2020-02-01", "2021-02-01", "2021-06-01", "2020-01-01", "2021-01-01"),
    e = c("2020-01-01", "2020-03-01", "2021-03-01", "2021-06-08", "2021-01-01", "2022-01-01"),
    stringsAsFactors = FALSE
  )
  expected_days <- c(0, 29, 28, 7, 366, 365)

  for (u in c("days", "weeks", "months", "years")) {
    denom <- switch(u, days = 1, weeks = 7, months = 30.4375, years = 365.25)
    res <- timeinterval(data = df, dx_date = "s", fu_date = "e",
                        time_format = "ymd", output_unit = u, time_basis = "standardized")
    expect_equal(ti_vals(res), expected_days / denom, tolerance = 1e-10)
  }

  # Sub-day ymdhms precision (30 hours = 1.25 days)
  res_ts <- timeinterval(
    data = data.frame(s = "2020-01-01 06:00:00", e = "2020-01-02 12:00:00"),
    dx_date = "s", fu_date = "e", time_format = "auto",
    output_unit = "days", timezone = "utc"
  )
  expect_equal(ti_vals(res_ts), 1.25, tolerance = 1e-12)
})

test_that("timeinterval matches closed-form mean, SD, median, person-time, and Student-t CIs", {
  local_load_timeinterval()
  x <- c(0, 7, 14, 21, 28)
  df <- data.frame(
    s = rep("2020-01-01", 5),
    e = as.character(as.Date("2020-01-01") + x),
    stringsAsFactors = FALSE
  )
  res <- timeinterval(data = df, dx_date = "s", fu_date = "e",
                      time_format = "ymd", output_unit = "days",
                      confidence_level = 95, show_summary = TRUE)
  expect_equal(ti_stat(res$summary$content, "Number of observations"), 5)
  expect_equal(ti_stat(res$summary$content, "Mean time"), 14)
  expect_equal(ti_stat(res$summary$content, "Standard deviation"), round(sqrt(122.5), 2), tolerance = 1e-6)
  expect_equal(ti_stat(res$summary$content, "Median time"), 14)
  expect_equal(ti_stat(res$summary$content, "Total person-time"), 70)

  for (cl in c(90, 95, 99)) {
    r_cl <- timeinterval(data = df, dx_date = "s", fu_date = "e",
                         time_format = "ymd", output_unit = "days",
                         confidence_level = cl)
    alpha <- 1 - cl / 100
    margin <- stats::qt(1 - alpha / 2, df = 4) * sqrt(122.5 / 5)
    exp_ci <- c(round(max(0, 14 - margin), 2), round(14 + margin, 2))
    expect_equal(ti_ci(r_cl$summary$content, cl), exp_ci, tolerance = 1e-6)
  }

  # Skewed fixture where lower bound is negative before clamping at 0
  x_skew <- c(0, 0, 0, 0, 100)
  df_skew <- data.frame(
    s = rep("2020-01-01", 5),
    e = as.character(as.Date("2020-01-01") + x_skew),
    stringsAsFactors = FALSE
  )
  res_skew <- timeinterval(data = df_skew, dx_date = "s", fu_date = "e",
                           time_format = "ymd", output_unit = "days",
                           confidence_level = 95)
  expect_equal(ti_ci(res_skew$summary$content, 95)[1], 0)
  expect_match(res_skew$summary$content, "The lower confidence limit is shown as 0, not as computed", fixed = TRUE)
})

test_that("timeinterval matches independent reference calculations on bundled datasets", {
  skip_if_not_installed("lubridate")
  local_load_timeinterval()
  root <- testthat::test_path("../..")
  load(file.path(root, "data/timeinterval_ymd.rda"))
  load(file.path(root, "data/timeinterval_landmark.rda"))

  exp_days <- as.numeric(as.Date(timeinterval_ymd$end_date) - as.Date(timeinterval_ymd$start_date))
  res_ymd <- timeinterval(data = timeinterval_ymd, dx_date = "start_date", fu_date = "end_date",
                          time_format = "ymd", output_unit = "months")
  expect_equal(ti_vals(res_ymd), exp_days / 30.4375, tolerance = 1e-8)

  exp_lm_raw <- as.numeric(as.Date(timeinterval_landmark$last_contact) - as.Date(timeinterval_landmark$enrollment_date)) / 30.4375
  keep <- !is.na(exp_lm_raw) & (exp_lm_raw >= 6)
  res_lm <- timeinterval(data = timeinterval_landmark, dx_date = "enrollment_date", fu_date = "last_contact",
                         time_format = "ymd", output_unit = "months",
                         use_landmark = TRUE, landmark_time = 6)
  expect_equal(ti_vals(res_lm), exp_lm_raw[keep] - 6, tolerance = 1e-8)
  expect_equal(ti_rownums(res_lm), which(keep))
})

test_that("timeinterval satisfies metamorphic invariance laws (permutation, unit scaling, shift, irrelevant cols)", {
  local_load_timeinterval()
  df <- data.frame(
    s = c("2020-01-01", "2020-02-15", "2020-05-10", "2020-08-20", "2020-11-05"),
    e = c("2020-04-01", "2020-06-15", "2020-09-10", "2021-01-20", "2021-05-05"),
    stringsAsFactors = FALSE
  )
  r0 <- timeinterval(data = df, dx_date = "s", fu_date = "e",
                     time_format = "ymd", output_unit = "days")
  perm <- c(4, 2, 5, 1, 3)
  rp <- timeinterval(data = df[perm, ], dx_date = "s", fu_date = "e",
                     time_format = "ymd", output_unit = "days")
  expect_equal(ti_vals(rp), ti_vals(r0)[perm], tolerance = 1e-12)
  expect_identical(rp$summary$content, r0$summary$content)

  # Unit scaling identity
  rw <- timeinterval(data = df, dx_date = "s", fu_date = "e", time_format = "ymd", output_unit = "weeks")
  rm <- timeinterval(data = df, dx_date = "s", fu_date = "e", time_format = "ymd", output_unit = "months")
  ry <- timeinterval(data = df, dx_date = "s", fu_date = "e", time_format = "ymd", output_unit = "years")
  expect_equal(ti_vals(rw) * 7, ti_vals(r0), tolerance = 1e-12)
  expect_equal(ti_vals(rm) * 30.4375, ti_vals(r0), tolerance = 1e-12)
  expect_equal(ti_vals(ry) * 365.25, ti_vals(r0), tolerance = 1e-12)

  # Constant date shift invariance (+366 days)
  df_shift <- data.frame(
    s = as.character(as.Date(df$s) + 366),
    e = as.character(as.Date(df$e) + 366),
    stringsAsFactors = FALSE
  )
  rs <- timeinterval(data = df_shift, dx_date = "s", fu_date = "e",
                     time_format = "ymd", output_unit = "days")
  expect_equal(ti_vals(rs), ti_vals(r0), tolerance = 1e-12)
})

test_that("timeinterval handles boundary and degenerate inputs without silent failure or NaN/Inf", {
  local_load_timeinterval()

  # Empty and all-NA datasets
  r_empty <- timeinterval(data = data.frame(s = character(0), e = character(0)),
                          dx_date = "s", fu_date = "e", time_format = "ymd")
  expect_match(r_empty$messages$content, "Data frame is empty", fixed = TRUE)
  expect_null(ti_vals(r_empty))

  r_na <- timeinterval(data = data.frame(s = rep(NA_character_, 3), e = rep("2020-01-01", 3)),
                       dx_date = "s", fu_date = "e", time_format = "ymd")
  expect_match(r_na$messages$content, "contains only missing", fixed = TRUE)
  expect_null(ti_vals(r_na))

  # Single row (n = 1) and constant intervals (SD = 0)
  r_n1 <- timeinterval(data = data.frame(s = "2020-01-01", e = "2020-01-11"),
                       dx_date = "s", fu_date = "e", time_format = "ymd", output_unit = "days")
  expect_equal(ti_vals(r_n1), 10)
  expect_match(r_n1$summary$content, "Standard deviation: NA", fixed = TRUE)
  expect_match(r_n1$messages$content, "Only one interval could be calculated", fixed = TRUE)

  r_sd0 <- timeinterval(data = data.frame(s = rep("2020-01-01", 4), e = rep("2020-01-11", 4)),
                        dx_date = "s", fu_date = "e", time_format = "ymd", output_unit = "days")
  expect_match(r_sd0$summary$content, "confidence interval has zero width", fixed = TRUE)

  # 5-digit spreadsheet serials rejected; 8-digit packed dates parsed
  r_serial <- timeinterval(data = data.frame(s = c("43831", "43862"), e = c("43900", "43950")),
                           dx_date = "s", fu_date = "e", time_format = "ymd")
  expect_match(r_serial$messages$content, "five-digit numbers", fixed = TRUE)
  expect_null(ti_vals(r_serial))

  r_compact <- timeinterval(data = data.frame(s = c("20200101", "20200201"), e = c("20200601", "20200701")),
                            dx_date = "s", fu_date = "e", time_format = "ymd", output_unit = "days")
  expect_equal(ti_vals(r_compact), c(152, 151))
})

test_that("VAL-timeinterval-01: calendar-aware month calculation is monotonic across month-end rollback", {
  skip("VAL-timeinterval-01 open defect: .calculateCalendarIntervals divides remainder_days by days_in_month(remainder_start) instead of days to next anniversary, causing 2021-01-31 -> 2021-03-30 (2.071m) to exceed 2021-01-31 -> 2021-03-31 (2.000m). Remove this skip when fixed.")
  local_load_timeinterval()
  df <- data.frame(
    s = rep("2021-01-31", 4),
    e = c("2021-03-28", "2021-03-29", "2021-03-30", "2021-03-31"),
    stringsAsFactors = FALSE
  )
  res <- timeinterval(data = df, dx_date = "s", fu_date = "e",
                      time_format = "ymd", output_unit = "months", time_basis = "calendar")
  vals <- ti_vals(res)
  expect_true(all(diff(vals) > 0))
  expect_equal(vals[4], 2.0, tolerance = 1e-12)
})

test_that("VAL-timeinterval-02: remove_extreme operates on post-negative-filter intervals without contradictory warnings", {
  skip("VAL-timeinterval-02 open defect: remove_extreme computes q99 and n_intervals on pre-filter raw vector including negative values, dropping the sole positive interval while simultaneously warning that 'none was removed' and 'dropped 1'. Remove this skip when fixed.")
  local_load_timeinterval()
  df <- data.frame(
    s = c(rep("2020-11-01", 50), "2020-01-01"),
    e = c(rep("2020-01-01", 50), "2028-05-01"),
    stringsAsFactors = FALSE
  )
  res <- timeinterval(data = df, dx_date = "s", fu_date = "e",
                      time_format = "ymd", output_unit = "months",
                      remove_negative = TRUE, remove_extreme = TRUE, extreme_multiplier = 2)
  expect_equal(sum(!is.na(ti_vals(res))), 1L)
  expect_false(grepl("none was removed", res$messages$content, fixed = TRUE) &&
               grepl("Extreme-value removal dropped 1", res$messages$content, fixed = TRUE))
})

test_that("VAL-timeinterval-03: landmark plausibility and unit-mixup warnings use post-filter non-NA intervals", {
  skip("VAL-timeinterval-03 open defect: landmark unit-mixup check is silenced by a single NA row (excluded_count == 0 includes na_excluded), and late-landmark check uses pre-filter median_interval instead of post-filter median. Remove this skip when fixed.")
  local_load_timeinterval()

  # (1) Unit-mixup warning must fire even when 1 NA row is present
  df_na <- data.frame(
    s = c(rep("2020-01-01", 20), NA_character_),
    e = c(rep("2021-02-04", 20), NA_character_),
    stringsAsFactors = FALSE
  )
  res_na <- timeinterval(data = df_na, dx_date = "s", fu_date = "e",
                         time_format = "ymd", output_unit = "days",
                         use_landmark = TRUE, landmark_time = 6)
  expect_match(res_na$messages$content, "entering a value meant as months while the output unit is days", fixed = TRUE)

  # (2) Late-landmark warning must not fire when only 6 of 20 (30%) post-filter observations are below landmark
  df_neg <- data.frame(
    s = c(rep("2020-06-01", 10), rep("2020-01-01", 6), rep("2020-01-01", 14)),
    e = c(rep("2020-01-01", 10), rep("2020-05-02", 6), rep("2021-01-01", 14)),
    stringsAsFactors = FALSE
  )
  res_neg <- timeinterval(data = df_neg, dx_date = "s", fu_date = "e",
                          time_format = "ymd", output_unit = "months",
                          remove_negative = TRUE, use_landmark = TRUE, landmark_time = 6)
  expect_false(grepl("more than half the cohort could not reach it", res_neg$messages$content, fixed = TRUE))
})

test_that("VAL-timeinterval-04: ymdhms timestamps on today's date are not falsely flagged as future dates", {
  skip("VAL-timeinterval-04 open defect: .assessDataQuality compares POSIXct > Sys.Date() (which coerces Sys.Date() to 00:00:00 UTC on today's date), flagging today's timestamps as future dates. Remove this skip when fixed.")
  local_load_timeinterval()
  today_str <- format(Sys.Date(), "%Y-%m-%d")
  df <- data.frame(
    s = rep("2020-01-01 08:00:00", 5),
    e = rep(paste0(today_str, " 12:00:00"), 5),
    stringsAsFactors = FALSE
  )
  res <- timeinterval(data = df, dx_date = "s", fu_date = "e",
                      time_format = "ymdhms", output_unit = "days",
                      timezone = "utc", include_quality_metrics = TRUE)
  expect_false(grepl("date values are in the future", res$messages$content, fixed = TRUE))
  expect_false(grepl("dates in the future detected", res$qualityAssessment$content, fixed = TRUE))
})

test_that("VAL-timeinterval-05: negative-interval share threshold (10%) is invariant to appending all-NA rows", {
  skip("VAL-timeinterval-05 open defect: neg_total uses nrow(self$data) instead of non-missing interval count, so appending 1 all-NA row dilutes 1/10 (10%) to 1/11 (9.1%) and releases withheld nlSummary. Remove this skip when fixed.")
  local_load_timeinterval()
  df <- data.frame(
    s = c("2020-12-01", rep("2020-01-01", 9), NA_character_),
    e = c(rep("2020-06-01", 10), NA_character_),
    stringsAsFactors = FALSE
  )
  res <- timeinterval(data = df, dx_date = "s", fu_date = "e",
                      time_format = "ymd", remove_negative = TRUE, show_summary = TRUE)
  expect_match(res$messages$content, "Strong Warning:", fixed = TRUE)
  expect_match(res$nlSummary$content, "Clinical Summary withheld", fixed = TRUE)
})

